import sys

import six


def exception_reraise_decorator(original_exception, reraised_exception):
    """
    :param original_exception: originally raised exception
    :param reraised_exception: exception that will be raised instead of original
    :return:
    """
    def real_decorator(func):
        """
        :param func:
        :return:
        """
        def inner(*args, **kwargs):
            """
            :param func:
            :return:
            """
            try:
                result = func(*args, **kwargs)
            except original_exception as exp:
                last_create_exception_stacktrace = sys.exc_info()[2]
                new_excp = reraised_exception(str(exp))
                new_excp.__dict__ = exp.__dict__
                six.reraise(reraised_exception, new_excp, last_create_exception_stacktrace)
            return result
        return inner
    return real_decorator
